  // --- sync tier: static offset per pair, seconds scale
  syncSearchMs: 'auto', // 'auto' => SYNC_SEARCH_MAX_MS
  syncMaxBlocks: 24,
  // Wider than coarse.js's 15 ms default on purpose: genuine blocks disagree by
  // the whole acoustic swing here, far more than a boom/lav pair does, and the
  // default would reject valid pairs as 'no-correlation'.
