  // --- baseline tier: affine clock model a + b*t
  baselineFrame: 2048, // 256 ms @ 8 kHz
  baselineHop: 2048, // 256 ms — see baselineTrimFraction for why it is this fine
  baselineSearchMs: 30,
  baselineExclusionMs: 1.0,
  baselineBlockSec: 20,
  baselineMinBlockPoints: 8,
  baselineMinBlocks: 3,
  // The mid-range is taken between TRIMMED extremes, by count, not between
  // fixed quantiles. A q10/q90 pair silently fails once the speaking split
  // passes ~85/15: q10 lands inside the majority mode and the estimate
  // collapses onto it. That is not an edge case — an interviewer who barely
  // talks is a 95/5 split — and it is the worst possible failure, because a
  // baseline sitting on the majority mode means the dominant speaker never
  // registers as leading. Trimming by count keeps the estimate on the true
  // range as long as the minority mode has more than `baselineMinTail` frames
  // in the block, which is what the 256 ms hop is buying.
  baselineTrimFraction: 0.02,
  baselineMinTail: 1,
  // Capped so the pooled offset estimate keeps resolving a small minority mode
  // however long the take is: the trim must stay well inside the rarer mode,
  // and that mode's share does not grow with duration.
  baselineMaxTail: 16,

  // --- attribution tier: per-frame acoustic TDOA
  // 64 ms is what the correlation needs; 16 ms is what the ballistics need.
  // Decoupling them is the point — you cannot correlate over 16 ms, and you
  // cannot open a mic on an 85 ms grid.
  frameSize: 512, // 64 ms @ 8 kHz
  hop: 128, // 16 ms @ 8 kHz -> 62.5 fps
  searchMs: 8, // +/- around the fitted baseline (~2.7 m)
  exclusionMs: 0.5,
  deadbandMs: 0.5, // 17 cm; absorbs residual baseline error
  leadFullMs: 3.0, // ~1 m; where the lead cue saturates
  confidenceGate: 1.5, // matches the engine-wide default
  candidateWindowDb: 15,
  minCandidates: 3,

  // Pairs are not equally trustworthy, and averaging them as if they were lets
