  spreadPlausibleMs: 10,
  // A pair is never discounted below this, however implausible its geometry.
  minReliability: 0.15,
  // 'equal' restores the old behaviour, for ablation.
  pairWeighting: 'reliability', // 'reliability' | 'equal'

  // --- scoring
