  // TIMING says its owner was the source — see refineReferenceLevels. 'p95' is
  // the single-pass version it replaced; 'off' disables normalisation entirely.
  levelNormalise: 'lead', // 'lead' | 'p95' | 'off'
  // A mic needs this many frames where it clearly led before its own speech is
  // a better reference than its overall p95.
  leadRefMinFrames: 40,
  leadRefThreshold: 0.4,
  leadGainDb: 12, // timing evidence is worth up to this much level

  // Spectral tilt: the third cue, and the only one that does not depend on the
  // mics being far apart.
  //
  // Direct sound is bright and sharp-edged. The same words reaching any other
  // mic have been through air, clothing and the room, and arrive low-passed and
