  // against how bright that mic gets when its OWN wearer talks — so a dull
  // capsule is not permanently penalised for being dull.
  tiltHz: 2000,
  tiltWeight: 1.0,
  tiltFloorDb: -12, // a single wild frame cannot outvote everything else

  activationSpanDb: 6,
  // Below this much activity there is no localisable source, so there is no
