  inactiveThreshold: 0.05,

  // --- clustering
  // Frames are grouped by WHERE the sound came from, not by which mic scored
  // highest — see clusterSpeakers.
  attribution: 'cluster', // 'cluster' | 'score'
  clusterIters: 20,
  // How many dB one millisecond of arrival difference is worth when measuring
  // how alike two frames are. Puts the two halves of the signature on a
  // comparable footing; timing is the more trustworthy half, so it is weighted
  // up rather than merely included.
  clusterTauScaleDb: 3,
  clusterMinFrames: 30,
  // Clustering is only better than per-mic scoring when the groups actually
  // SEPARATE. With mics nearly equidistant the fingerprints overlap, frames get
  // assigned to the wrong group, and scoring — which still has the level cue to
