  // used only if it earns it.
  clusterMinQuality: 0.35,
  // ...and it must broadly AGREE with what the per-frame scores already say.
  //
  // Clustering is here to steady a decision, not to overrule one. Where the
  // fingerprints separate cleanly it removes the flicker and the trim
