function clamp(v, lo, hi) {
  if (v < lo) return lo;
  if (v > hi) return hi;
  return v;
}

/**
 * Range of `values` between trimmed extremes, and its midpoint.
 *
 * Trimming is by COUNT, not by quantile: `k` entries are dropped from each end
 * and the k-th smallest and k-th largest define the range. That keeps the
 * midpoint on the true range whatever the mix of the two modes, where a fixed
 * quantile pair drifts onto the majority one (see baselineTrimFraction).
 *
 * @returns {{ lo, hi, mid, range }}
 */
function trimmedRange(values, trimFraction, minTail, maxTail = Infinity) {
  const n = values.length;
  if (!n) return { lo: 0, hi: 0, mid: 0, range: 0 };
  const sorted = Float64Array.from(values).sort();
  const maxK = Math.floor((n - 1) / 2);
  const want = clamp(Math.round(trimFraction * n), minTail, maxTail);
  const k = Math.min(maxK, want);
  const lo = sorted[k];
  const hi = sorted[n - 1 - k];
  return { lo, hi, mid: (lo + hi) / 2, range: hi - lo };
}

/**
 * RBJ high-pass, used to measure how much of a frame's energy is in the top
 * band. One pass over the whole signal is far cheaper than an FFT per frame,
 * and tilt does not need frequency resolution — only a ratio.
 */
function highpassed(x, fc, fs) {
  const w0 = (2 * Math.PI * fc) / fs;
  const cw = Math.cos(w0);
  const alpha = Math.sin(w0) / (2 * Math.SQRT1_2);
  const a0 = 1 + alpha;
  const b0 = ((1 + cw) / 2) / a0;
  const b1 = (-(1 + cw)) / a0;
  const b2 = ((1 + cw) / 2) / a0;
  const a1 = (-2 * cw) / a0;
  const a2 = (1 - alpha) / a0;
  const y = new Float64Array(x.length);
  let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
  for (let i = 0; i < x.length; i++) {
    const v = b0 * x[i] + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2;
    x2 = x1; x1 = x[i];
    y2 = y1; y1 = v;
    y[i] = v;
  }
  return y;
}

const hannCache = new Map();

function hann(n) {
  let w = hannCache.get(n);
  if (!w) {
    w = new Float64Array(n);
    for (let i = 0; i < n; i++) w[i] = 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / n);
    hannCache.set(n, w);
  }
  return w;
}

/** paddedSlice into a caller-owned buffer: the attribution loop runs this tens
 *  of thousands of times and has no reason to allocate on every one. */
function fillSlice(out, src, from) {
  out.fill(0);
  const start = Math.max(0, from);
  const end = Math.min(src.length, from + out.length);
  for (let i = start; i < end; i++) out[i - from] = src[i];
  return out;
}

/** p95 of the values at the given indices — the level a mic reaches when its
 *  own wearer is actually talking, which is what makes levels comparable
 *  between recorders trimmed differently. */
function percentile(values, indices, q) {
  if (!indices.length) return 0;
  const picked = new Float64Array(indices.length);
  for (let i = 0; i < indices.length; i++) picked[i] = values[indices[i]];
  picked.sort();
  return picked[Math.min(picked.length - 1, Math.floor(q * (picked.length - 1)))];
}

/**
 * Static offset between two mics, symmetric in its arguments.
 *
 * estimateStaticOffset derives its silence gate from the FIRST argument only
 * (coarse.js), so f(a,b) !== f(b,a) — which would make the whole feature
 * depend on the order mics arrive in. Passing an explicit gate built from both
 * signals removes that.
 *
 * @returns {{ ok, offsetSamples, confidence, reason }} offset in samples at
 *   opts.sampleRate; positive means `b` lags `a`.
 */
function pairSyncOffset(a, b, opts) {
  const o = { ...AUTOMIX_DEFAULTS, ...opts };
  const sampleRate = o.sampleRate;
  if (!sampleRate) throw new Error('pairSyncOffset: sampleRate required');
  const maxShiftMs = o.syncSearchMs === 'auto' ? SYNC_SEARCH_MAX_MS : o.syncSearchMs;
  const rmsGateDb = Math.min(adaptiveGateDb(a), adaptiveGateDb(b));
  const r = estimateStaticOffset(a, b, {
    sampleRate,
    maxShiftMs,
    confidenceGate: o.confidenceGate,
    maxBlocks: o.syncMaxBlocks,
    agreementToleranceMs: o.syncAgreementToleranceMs,
    rmsGateDb,
  });
  return {
    ok: !!r.ok,
    offsetSamples: r.ok ? r.offsetSamples : 0,
    confidence: r.ok ? r.confidence : 0,
    reason: r.reason || null,
  };
}

/**
 * Sweep the raw lag between two mics on a coarse grid, centred on a known
 * static offset. This is the input the affine clock model is fitted to; it is
 * deliberately unsmoothed, because every smoother in the engine is built to
 * remove exactly the variation we are trying to measure.
 *
 * @param {Float64Array} a
 * @param {Float64Array} b
 * @param {number|{a:number,b:number}} d0 centre of the search: either a
 *   static offset in samples, or an affine clock model a + b*t. A long take
 *   drifts further than the search window is wide, so the window has to
 *   follow the clock rather than sit on one number.
 * @returns {{ centers: Float64Array, lags: Float64Array, weights: Float64Array }}
 *   one entry per frame on a uniform grid; weight 0 marks a gated frame, whose
 *   lag is meaningless and must not be fitted.
 */
function measurePairLags(a, b, d0, opts) {
  const o = { ...AUTOMIX_DEFAULTS, ...opts };
  const sampleRate = o.sampleRate;
  if (!sampleRate) throw new Error('measurePairLags: sampleRate required');
  const F = o.baselineFrame;
  const hop = o.baselineHop;
  const L = Math.round((o.baselineSearchMs / 1000) * sampleRate);
  const exclusion = Math.max(1, Math.round((o.baselineExclusionMs / 1000) * sampleRate));
  const centreAt = typeof d0 === 'number'
    ? () => Math.round(d0)
    : (t) => Math.round(d0.a + d0.b * t);
  const gateDb = Math.min(adaptiveGateDb(a), adaptiveGateDb(b));
  const len = Math.min(a.length, b.length);

  const centers = [];
  const lags = [];
  const weights = [];
  for (let t0 = 0; t0 + F <= len; t0 += hop) {
    const refBlock = a.subarray(t0, t0 + F);
    const rms = rmsOf(refBlock);
    const centre = centreAt(t0 + F / 2);
    centers.push(t0 + F / 2);
    if (db(rms) < gateDb) {
      lags.push(centre);
      weights.push(0);
      continue;
    }
    // Length is DERIVED from F and L, never computed independently: gccPhat
    // throws unless the slice is exactly F + 2*L, and an off-by-one here is
    // the likeliest first failure once `centre` starts varying per frame.
    const slice = paddedSlice(b, t0 - L + centre, F + 2 * L);
    const r = gccPhat(refBlock, slice, L, { exclusionSamples: exclusion });
    lags.push(r.bestLag + centre);
    weights.push(clamp((r.peakRatio - o.confidenceGate) / o.confidenceGate, 0, 1));
  }
  return {
    centers: Float64Array.from(centers),
    lags: Float64Array.from(lags),
    weights: Float64Array.from(weights),
  };
}

/**
 * Fit the clock model `baseline(t) = a + b*t` to a raw per-frame lag series,
 * leaving the acoustic TDOA as the residual.
 *
 * WHY MID-RANGE, NOT MEDIAN. In a two-person exchange the raw lag is bimodal:
 * +3.5 ms while A talks, -3.5 ms while B talks. The median lands on whichever
 * mode holds more speaking time, so a 70/30 split biases it by ~1.4 ms — 40%
 * of the whole signal. The mid-range of the two modes is the clock offset
 * whatever the split. When one participant never talks the distribution is
 * unimodal and the mid-range sits on that mode, so the silent one never leads
 * — which is the right answer, reached by accident. Do not "fix" this to a
 * median.
 *
 * KNOWN LIMITATION, K >= 3. The mid-range assumes both members of the pair take
 * turns being the nearest mic, so the two modes straddle the clock offset. With
 * three or more participants that is not the whole story: when the source is
 * nearest to NEITHER member, the true residual is 0, which is a third mode
 * sitting between them. If one participant never speaks, pair (i, silent) only
 * ever sees {+delta, 0} and the mid-range lands at delta/2 — so the silent mic
 * appears to LEAD during everyone else's turns, and its genuine lag during the
 * rest cancels it out to roughly neutral. The lead cue then abstains and the
 * level cue decides alone. Measured effect: a never-speaking participant is
 * ducked ~3 dB rather than the ~12 dB it deserves, which is the right direction
 * but weak. Fixing it properly means estimating per-mic clock offsets globally
 * across all pairs instead of pair by pair, which is a larger change than this
 * slice — see the note in docs/architecture.md.
 *
 * WHY AFFINE. Recorder drift is a clock-ratio error: monotone and linear to
 * well under a millisecond over a five-minute take. The acoustic swing is a
 * roughly zero-mean bimodal perturbation on top. A line is both the right
 * physics and the only model that cannot absorb the signal.
 *
 * @returns {{ a, b, spreadSamples, usable, blocks, points }}
 *   `a` and `b` are in samples and samples-per-sample; spreadSamples is the
 *   q90-q10 of the residual, i.e. how much acoustic swing this pair actually
 *   sees. `usable` is false when that swing is too small to carry a decision —
 *   two effectively co-located mics, whose lead sign is noise.
 */
function fitPairBaseline(centers, lags, weights, opts) {
  const o = { ...AUTOMIX_DEFAULTS, ...opts };
  const sampleRate = o.sampleRate;
  if (!sampleRate) throw new Error('fitPairBaseline: sampleRate required');

  const pts = [];
  for (let i = 0; i < centers.length; i++) {
    if (weights[i] > 0) pts.push({ t: centers[i], v: lags[i], w: weights[i] });
  }
  const empty = { a: 0, b: 0, spreadSamples: 0, usable: false, blocks: 0, points: pts.length };
  if (!pts.length) return empty;

  // Per-block mid-range, then a line through the block mid-ranges.
  const blockLen = Math.max(1, Math.round(o.baselineBlockSec * sampleRate));
  const byBlock = new Map();
  for (let i = 0; i < pts.length; i++) {
    const k = Math.floor(pts[i].t / blockLen);
    let arr = byBlock.get(k);
    if (!arr) { arr = []; byBlock.set(k, arr); }
    arr.push(pts[i]);
  }

  const knots = [];
  for (const arr of byBlock.values()) {
    if (arr.length < o.baselineMinBlockPoints) continue;
    const mid = trimmedRange(arr.map((p) => p.v), o.baselineTrimFraction, o.baselineMinTail, o.baselineMaxTail).mid;
    let sw = 0;
    let swt = 0;
    for (let i = 0; i < arr.length; i++) { sw += arr[i].w; swt += arr[i].w * arr[i].t; }
    if (!(sw > 0)) continue;
    knots.push({ t: swt / sw, y: mid, w: sw });
  }

  // Slope and offset are estimated from different sets, because they need
  // different things. The SLOPE needs time spread, so it comes from per-block
  // knots. The OFFSET needs the two acoustic modes to be resolved, and a
  // single 20 s block holds too few frames to resolve a small minority mode —
  // so it is taken from every point at once, after detrending. Any collapse a
  // knot suffers is common-mode across blocks (the speaking split is roughly
  // constant over a take), so it cancels in the slope and only the pooled
  // intercept has to be robust to it.
  let b = 0;
  if (knots.length >= o.baselineMinBlocks) {
    // Centre the time axis before fitting. t reaches ~2.4e6 samples over a
    // five-minute take, so an uncentred normal equation squares that into
    // 5.8e12 and loses precision where it matters most — in the slope.
    let sw = 0;
    let swt = 0;
    for (let i = 0; i < knots.length; i++) { sw += knots[i].w; swt += knots[i].w * knots[i].t; }
    const tm = swt / sw;
    let sxx = 0;
    let sxy = 0;
    for (let i = 0; i < knots.length; i++) {
      const dt = knots[i].t - tm;
      sxx += knots[i].w * dt * dt;
      sxy += knots[i].w * dt * knots[i].y;
    }
    b = sxx > 0 ? sxy / sxx : 0;
  }

  const detrended = new Float64Array(pts.length);
  for (let i = 0; i < pts.length; i++) detrended[i] = pts[i].v - b * pts[i].t;
  const a = trimmedRange(detrended, o.baselineTrimFraction, o.baselineMinTail, o.baselineMaxTail).mid;

  const resid = new Float64Array(pts.length);
  for (let i = 0; i < pts.length; i++) resid[i] = pts[i].v - (a + b * pts[i].t);
  const spreadSamples = trimmedRange(resid, o.baselineTrimFraction, o.baselineMinTail, o.baselineMaxTail).range;
  const spreadMs = (spreadSamples / sampleRate) * 1000;

  return {
    a,
    b,
    spreadSamples,
    usable: spreadMs > 2 * o.deadbandMs,
    blocks: knots.length,
    points: pts.length,
  };
}

/**
 * Solve the clock model for every unordered pair. Pairs are keyed by mic index
 * with i < j so a pair means the same thing however the mics were ordered on
 * the way in — see the symmetry note on attributeSpeakers.
 */
function solvePairs(mics, o) {
  const K = mics.length;
  const pairs = [];
  for (let i = 0; i < K; i++) {
    for (let j = i + 1; j < K; j++) {
      const sync = pairSyncOffset(mics[i], mics[j], o);
      if (!sync.ok) {
        pairs.push({
          i, j, baseline: { a: 0, b: 0 }, spreadMs: 0, usable: false, reliability: 0,
          syncMs: 0, syncConfidence: 0, reason: sync.reason || 'no-sync',
          confidentFrames: 0, tau: null, w: null,
        });
        continue;
      }
      // Seed the sweep with a drifting centre.
      //
      // A single static offset is only good for as long as the clocks agree.
      // At 20 ppm a 43-minute take drifts ~52 ms, which is wider than the
      // +/-30 ms window the sweep searches — so the true lag walks out of the
      // window partway through and everything after it is noise. Two static
      // estimates, one near each end, give the slope directly and cost two more
      // coarse passes.
      const len = Math.min(mics[i].length, mics[j].length);
      let centre = sync.offsetSamples;
      const third = Math.floor(len / 3);
      if (third > o.baselineFrame * 8) {
        const early = pairSyncOffset(mics[i].subarray(0, third), mics[j].subarray(0, third), o);
        const late = pairSyncOffset(
          mics[i].subarray(len - third), mics[j].subarray(len - third), o);
        if (early.ok && late.ok) {
          const tEarly = third / 2;
          const tLate = len - third / 2;
          const slope = (late.offsetSamples - early.offsetSamples) / (tLate - tEarly);
          // A slope beyond a few hundred ppm is a failed probe, not a clock.
          if (Math.abs(slope) < 5e-4) {
            centre = { a: early.offsetSamples - slope * tEarly, b: slope };
          }
        }
      }
      const raw = measurePairLags(mics[i], mics[j], centre, o);
      const fit = fitPairBaseline(raw.centers, raw.lags, raw.weights, o);
      let confident = 0;
      for (let k = 0; k < raw.weights.length; k++) if (raw.weights[k] > 0) confident++;
      const spreadMs = (fit.spreadSamples / o.sampleRate) * 1000;
      // Falls from 1 at a plausible room-sized spread to 0 where the spread
      // fills the whole search window, i.e. where the lag is noise.
      const maxSpreadMs = 2 * o.baselineSearchMs;
      // Floored, not zeroed. A pair whose spread looks implausible is usually
      // still carrying SOME information — people move over a long take, and a
      // spread that would be absurd over 30 s is ordinary over 40 minutes.
      // Driving reliability to exactly 0 silenced such pairs outright and then
      // reported "arrival time gave nothing", which blamed the correlation for
      // a decision this weighting had made.
      const plausible = o.minReliability + (1 - o.minReliability) * clamp(
        1 - (spreadMs - o.spreadPlausibleMs) / Math.max(1e-6, maxSpreadMs - o.spreadPlausibleMs),
        0, 1);
      pairs.push({
        i,
        j,
        baseline: { a: fit.a, b: fit.b },
        spreadMs,
        reliability: plausible * clamp(raw.weights.length ? confident / raw.weights.length : 0, 0, 1),
        // A pair with no acoustic swing has no geometry to read a lead from,
        // and its sign would be noise fed in at full confidence.
        usable: fit.usable,
        syncMs: (sync.offsetSamples / o.sampleRate) * 1000,
        syncConfidence: sync.confidence,
        reason: fit.usable ? null : 'no-geometry',
        confidentFrames: raw.weights.length ? confident / raw.weights.length : 0,
        tau: null,
        w: null,
      });
    }
  }
  return pairs;
}

/**
 * Per-frame speaker attribution across N mics.
 *
 * SYMMETRIC IN `mics`. There is no reference here; permuting the input must not
 * change who wins. Pairs are canonically ordered by mic index and every
 * accumulation is applied to both members with opposite sign, so the only
 * residual asymmetry is that gccPhat windows its ref argument and not its
 * slice — small, and bounded by the tolerance in the permutation test.
 *
 * Returns the CUES, not a decision: levels, lead, and the confidence in each.
 * Combining them into a winner and a gain is autoMixGains' job, so an ablation
 * on the scoring weights does not have to re-run tens of thousands of
 * correlations.
 *
 * @param {Array<Float64Array>} mics decimated signals, all at opts.sampleRate
 * @returns {object} see the fields assembled at the end of this function
 */
function attributeSpeakers(mics, opts) {
  const o = { ...AUTOMIX_DEFAULTS, ...opts };
  const fa = o.sampleRate;
  if (!fa) throw new Error('attributeSpeakers: sampleRate required');
  const K = mics.length;
  if (K < 2) throw new Error(`attributeSpeakers: need at least 2 mics, got ${K}`);

  const F = o.frameSize;
  const hop = o.hop;
  let len = mics[0].length;
  for (let m = 1; m < K; m++) len = Math.min(len, mics[m].length);
  const nFrames = len >= F ? Math.floor((len - F) / hop) + 1 : 0;
  if (!nFrames) throw new Error(`attributeSpeakers: signals too short (${len} < ${F})`);

  const pairs = solvePairs(mics, o);

  const frameCenters = new Float64Array(nFrames);
  const levelDb = [];
  const nLevelDb = [];
  const lead = [];
  const leadWeight = [];
  const gateDb = new Float64Array(K);
  const refDb = new Float64Array(K);
  for (let m = 0; m < K; m++) {
    levelDb.push(new Float64Array(nFrames));
    nLevelDb.push(new Float64Array(nFrames));
    lead.push(new Float64Array(nFrames));
    leadWeight.push(new Float64Array(nFrames));
    gateDb[m] = adaptiveGateDb(mics[m]);
  }

  // Pass 1: levels and spectral tilt. Both need a per-mic reference before any
  // scoring can happen, and both get one from the same set of frames.
  const tiltDb = [];
  const tiltRefDb = new Float64Array(K);
  const nTiltDb = [];
  for (let m = 0; m < K; m++) {
    tiltDb.push(new Float64Array(nFrames));
    nTiltDb.push(new Float64Array(nFrames));
  }
  const hp = mics.map((x) => highpassed(x, o.tiltHz, fa));
  for (let f = 0; f < nFrames; f++) {
    const t0 = f * hop;
    frameCenters[f] = t0 + F / 2;
    for (let m = 0; m < K; m++) {
      levelDb[m][f] = db(rmsOf(mics[m], t0, t0 + F));
      // High-band share of this frame, in dB. Independent of the mic's trim,
      // because it is a ratio taken within one mic.
      tiltDb[m][f] = db(rmsOf(hp[m], t0, t0 + F)) - levelDb[m][f];
    }
  }
  hp.length = 0;

  // K-weighted energy per frame, for the absolute loudness target.
  //
  // One mic at a time through a shared scratch buffer, unlike the tilt filter
  // above: a full-length filtered copy is the largest array this function
  // touches, and only the per-frame energies outlive it.
  //
  // MEASURED ON THE DECIMATED SIGNAL, which reads about 0.4 LU LOW: the
  // anti-alias filter takes the top of the speech band with it, and K-weighting
  // lifts that band by 4 dB so it counts for more than it would in plain RMS.
  // Delivery therefore lands ~0.4 LU above the number asked for.
  //
  // Left uncorrected on purpose. It is a BIAS, not a per-track error — measured
  // at -0.32 to -0.52 LU across material as different as a 3.4 kHz-limited
  // fixture and a deliberately sibilant one (loudness.test.js) — so it shifts
  // the whole delivery slightly and moves no mic relative to another, which is
  // the property that matters. Subtracting a constant fitted on fixtures would
  // be a fudge factor that stops being right the first time the decimation
  // changes. Re-measuring at full rate would mean carrying an undecimated copy
  // of every mic through attribution: 6x the memory for half a decibel.
  //
  // Skipped rather than thrown on if the analysis rate is too low to place the
  // shelf (an unusual `decimation`): a loudness target is one feature, and it
  // must not take attribution down with it.
  const kMs = [];
  if (fa > 2 * KWEIGHT_MIN_HZ) {
    const scratch = new Float64Array(len);
    for (let m = 0; m < K; m++) {
      kWeight(mics[m], fa, scratch, len);
      const row = new Float64Array(nFrames);
      for (let f = 0; f < nFrames; f++) {
        const t0 = f * hop;
        let sum = 0;
        for (let k = 0; k < F; k++) {
          const v = scratch[t0 + k];
          sum += v * v;
        }
        row[f] = sum / F;
      }
      kMs.push(row);
    }
  }
  for (let m = 0; m < K; m++) {
    const active = [];
    for (let f = 0; f < nFrames; f++) if (levelDb[m][f] >= gateDb[m]) active.push(f);
    refDb[m] = active.length ? percentile(levelDb[m], active, 0.95) : 0;
    const sub = o.levelNormalise === 'off' ? 0 : refDb[m];
    for (let f = 0; f < nFrames; f++) nLevelDb[m][f] = levelDb[m][f] - sub;
  }

  const levelActivity = new Float64Array(nFrames);
  for (let f = 0; f < nFrames; f++) {
    let best = 0;
    for (let m = 0; m < K; m++) {
      const a = clamp((levelDb[m][f] - gateDb[m]) / o.activationSpanDb, 0, 1);
      if (a > best) best = a;
    }
    levelActivity[f] = best;
  }

  // Pass 2: per-frame time of arrival, pair by pair.
  const L = Math.max(1, Math.round((o.searchMs / 1000) * fa));
  const exclusion = Math.max(1, Math.round((o.exclusionMs / 1000) * fa));
  const win = hann(F);
  const refBuf = new Float64Array(F);
  const sliceBuf = new Float64Array(F + 2 * L);
  const coherence = new Float64Array(nFrames);
  // Before reliability weighting: how well the mics actually correlated,
  // as opposed to how much we chose to trust it.
  const rawCoherence = new Float64Array(nFrames);
  const usablePairs = pairs.filter((p) => p.usable);
  for (const p of usablePairs) {
    p.tau = new Float64Array(nFrames);
    p.w = new Float64Array(nFrames);
  }

  const candidate = new Uint8Array(K);
  const leadSpanMs = Math.max(1e-6, o.leadFullMs - o.deadbandMs);

  for (let f = 0; f < nFrames; f++) {
    const t0 = f * hop;

    // Candidate pruning caps the O(K^2) correlation count. The window is wide
    // (15 dB) against a discriminator that works at ~6 dB, and minCandidates
    // makes it a no-op for K <= 3 — it cannot affect the case this feature
    // exists for, only the cost of large casts.
    let loudest = -Infinity;
    for (let m = 0; m < K; m++) if (levelDb[m][f] > loudest) loudest = levelDb[m][f];
    let nCand = 0;
    for (let m = 0; m < K; m++) {
      candidate[m] = levelDb[m][f] >= loudest - o.candidateWindowDb ? 1 : 0;
      nCand += candidate[m];
    }
    if (nCand < o.minCandidates) {
      // Top up by level until the floor is met, so the set never collapses to
      // one mic and leaves the frame with no pair to read.
      const order = [];
      for (let m = 0; m < K; m++) order.push(m);
      order.sort((x, y) => levelDb[y][f] - levelDb[x][f]);
      for (let k = 0; k < Math.min(o.minCandidates, K); k++) candidate[order[k]] = 1;
    }

    let maxW = 0;
    let maxRawW = 0;
    for (const p of usablePairs) {
      const i = p.i;
      const j = p.j;
      if (!candidate[i] || !candidate[j]) continue;
      // Both mics must have signal: a gate on one side only would make the
      // result depend on which member of the pair came first.
      if (levelDb[i][f] < gateDb[i] || levelDb[j][f] < gateDb[j]) continue;

      const base = p.baseline.a + p.baseline.b * frameCenters[f];
      const baseInt = Math.round(base);
      const frac = base - baseInt;

      for (let k = 0; k < F; k++) refBuf[k] = mics[i][t0 + k] * win[k];
      // Length is derived from F and L. gccPhat throws on any other slice
      // length, and with baseInt varying per frame that is exactly where an
      // off-by-one would land.
      fillSlice(sliceBuf, mics[j], t0 + baseInt - L);
      const r = gccPhat(refBuf, sliceBuf, L, { exclusionSamples: exclusion });

      // tau > 0 means j lags i, i.e. i is nearer the source and LEADS.
      const tauMs = ((r.bestLag - frac) / fa) * 1000;
      const w = clamp((r.peakRatio - o.confidenceGate) / o.confidenceGate, 0, 1);
      const mag = clamp((Math.abs(tauMs) - o.deadbandMs) / leadSpanMs, 0, 1);
      const signed = tauMs < 0 ? -mag : mag;

      p.tau[f] = tauMs;
      p.w[f] = w;
      // Weight by the pair's reliability as well as this frame's confidence.
      // Without it a pair whose geometry is nonsense contributes exactly as
      // much as one that works, and on real material that halved the usable
      // timing signal.
      const wr = o.pairWeighting === 'equal' ? w : w * p.reliability;
      lead[i][f] += wr * signed;
      leadWeight[i][f] += wr;
      lead[j][f] -= wr * signed;
      leadWeight[j][f] += wr;
      if (wr > maxW) maxW = wr;
      if (w > maxRawW) maxRawW = w;
    }
    // One localisable source anywhere in the room is enough; a single dead mic
    // must not be able to switch the whole feature off, so this is a max.
    coherence[f] = maxW;
    rawCoherence[f] = maxRawW;
  }

  // Normalise by summed weight, not by pair count: an unnormalised score would
  // read 7 for a mic in an 8-mic take and 2 for the same mic in a 3-mic one,
  // and candidate pruning gives different mics different denominators anyway.
  const leadNorm = [];
  for (let m = 0; m < K; m++) {
    const out = new Float64Array(nFrames);
    for (let f = 0; f < nFrames; f++) {
      out[f] = leadWeight[m][f] > 0 ? lead[m][f] / leadWeight[m][f] : 0;
    }
    leadNorm.push(out);
  }

  // Second pass over the reference levels, now that timing has an opinion.
  //
  // p95 over a mic's active frames assumes its loudest 5% is its owner talking.
  // That breaks exactly where it matters most: on a hot preamp, bleed is loud
  // in absolute terms and pollutes the reference, so a mic set 14 dB hotter
  // than its neighbours ends up with a reference that is part its own voice and
  // part everyone else's. Timing does not care about trim, so the frames where
  // a mic clearly LED are a trim-independent sample of that mic's own speech —
  // and a far better reference.
  //
  // The frame set is hoisted out because the loudness measurement below needs
  // exactly the same one: refDb and speechLufs must describe the same speech,
  // or a report that shows both is comparing two different things.
  const ownFrames = [];
  const ownFromLead = new Uint8Array(K);
  for (let m = 0; m < K; m++) {
    const own = [];
    for (let f = 0; f < nFrames; f++) {
      if (leadNorm[m][f] >= o.leadRefThreshold && levelDb[m][f] >= gateDb[m]) own.push(f);
    }
    // Fall back to every active frame rather than trusting a handful: a
    // participant who barely speaks has no reliable sample of their own voice.
    if (own.length >= o.leadRefMinFrames) {
      ownFrames.push(own);
      ownFromLead[m] = 1;
      continue;
    }
    const active = [];
    for (let f = 0; f < nFrames; f++) if (levelDb[m][f] >= gateDb[m]) active.push(f);
    ownFrames.push(active);
  }

  if (o.levelNormalise === 'lead') {
    for (let m = 0; m < K; m++) {
      if (!ownFromLead[m]) continue;
      refDb[m] = percentile(levelDb[m], ownFrames[m], 0.95);
      // Same treatment for tilt: the reference is how bright this mic gets when
      // its own wearer is talking, so a dull capsule is not penalised for being
      // dull — only for being duller than itself.
      tiltRefDb[m] = percentile(tiltDb[m], ownFrames[m], 0.95);
    }
    for (let m = 0; m < K; m++) {
      for (let f = 0; f < nFrames; f++) nLevelDb[m][f] = levelDb[m][f] - refDb[m];
    }
  }

  // Absolute loudness of each person's own dialogue.
  //
  // This is the number a target is set against, and it is deliberately NOT the
  // integrated loudness of the track. A track's own loudness counts bleed and
  // room tone as programme, so the quietest participant — whose mic spends most
  // of the take catching everyone else — would read loud and be turned DOWN. It
  // is also not derivable from refDb: that is a p95 of frame RMS, a peak-ish
  // statistic on a dB scale with no defined relationship to a mean-square
  // loudness, and treating one as the other is off by the crest factor of
  // whoever is talking.
  const speechLufs = new Float64Array(K).fill(-Infinity);
  if (kMs.length) {
    for (let m = 0; m < K; m++) speechLufs[m] = gatedLufs(kMs[m], ownFrames[m]);
  }
  for (let m = 0; m < K; m++) {
    for (let f = 0; f < nFrames; f++) {
      nTiltDb[m][f] = clamp(tiltDb[m][f] - tiltRefDb[m], o.tiltFloorDb, 0);
    }
  }

  const result = {
    sampleRate: fa,
    frameSize: F,
    hop,
    nFrames,
    micCount: K,
    frameCenters,
    levelDb,
    refDb,
    speechLufs,
    ownFromLead,
    nLevelDb,
    tiltDb,
    tiltRefDb,
    nTiltDb,
    lead: leadNorm,
    leadWeight,
    coherence,
    rawCoherence,
    levelActivity,
    gateDb,
    pairs,
  };
  result.cluster = clusterSpeakers(result, o);
  return result;
}

/**
 * Combine the cues into a per-frame gain per mic.
 *
 * WINNER-RELATIVE, NOT SUM-RELATIVE. Dugan's gain_i = level_i / sum_j level_j
 * is built for gain-before-feedback in live PA, where holding the summed gain
 * constant is the whole point. In post it is actively wrong: three equal mics
 * in a pause each land 9.5 dB down, which is the "ducks everything during a
 * pause" failure that makes an auto-mixer worse than none. Scoring against the
 * winner gives the winner exactly 0 dB and makes every degenerate case a no-op.
 *
 * ACTIVITY IS A PRODUCT WITH COHERENCE, not a level gate alone. adaptiveGateDb
 * is relative to each mic's own level, so pure room tone sits ABOVE every mic's
 * gate and a level-only test would duck silence. Independent room tone gives
 * peakRatio ~ 1 on every pair, so coherence collapses and nothing is ducked.
 *
 * NEVER MUTES. maxDuckDb caps the depth: deeper pumps room tone audibly, and it
 * would destroy the material for the per-band stage that comes later — you
 * cannot unmask what has already been gated away.
 */
/**
 * Group frames by the acoustic signature of where the sound came from, and
 * decide once per group which mic owns it.
 *
 * WHY THIS RATHER THAN SCORING EACH MIC. Everything upstream produces per-mic
 * scores that are then compared; that is fragile because every one of those
 * scores degrades on hard material — level ties when trims are wrong, timing
 * ties when people stand close, tilt ties when the room is dry. Comparing
 * ABSOLUTE scores means any single cue going soft moves the answer.
 *
 * But the RELATIVE picture is far more stable. For one person speaking from one
 * place, the vector of inter-mic level differences and inter-mic arrival
 * differences is close to constant — it is a fingerprint of a position in the
 * room, not of a loudness. A trim change shifts every frame's fingerprint by the
 * same amount, so it cannot move a frame from one speaker's group to another's.
 * Group the frames by that fingerprint and the identity question is answered by
 * where a frame SITS rather than by which score happened to win.
 *
 * Three consequences worth having: no dependence on the level references being
 * right, no per-frame vote to flicker, and a participant who rarely speaks owns
 * a small group instead of disappearing.
 *
 * The winner for a group is read off the group's own centroid, from the TIMING
 * half of the signature only — arrival order does not care about trims.
 *
 * @returns {{ assign, clusterWinner, confidence, clusters, dims }}
 *   assign[f] is the group index, or -1 where the frame was not clustered.
 */
function clusterSpeakers(attribution, opts) {
  const o = { ...AUTOMIX_DEFAULTS, ...opts };
  const K = attribution.micCount;
  const nFrames = attribution.nFrames;
  const pairs = attribution.pairs.filter((p) => p.usable && p.tau);

  // Feature vector: every inter-mic level difference, then every inter-mic
  // arrival difference. Both are differences on purpose — an absolute level or
  // an absolute lag would drag the mic's own trim and the recorders' clock
  // offset into the fingerprint.
  const levelPairs = [];
  for (let i = 0; i < K; i++) for (let j = i + 1; j < K; j++) levelPairs.push([i, j]);
  const dims = levelPairs.length + pairs.length;
  const empty = {
    assign: new Int32Array(nFrames).fill(-1),
    clusterWinner: new Int32Array(K).fill(-1),
    confidence: new Float64Array(nFrames),
    clusters: 0,
    dims,
  };
  if (!dims || nFrames < o.clusterMinFrames) return empty;

  const idx = [];
  for (let f = 0; f < nFrames; f++) {
    if (attribution.levelActivity[f] >= 0.5) idx.push(f);
  }
  if (idx.length < o.clusterMinFrames * K) return empty;

  const feat = new Float64Array(idx.length * dims);
  for (let n = 0; n < idx.length; n++) {
    const f = idx[n];
    let d = 0;
    for (const [i, j] of levelPairs) {
      feat[n * dims + d++] = attribution.levelDb[i][f] - attribution.levelDb[j][f];
    }
    for (const p of pairs) {
      // Unconfident frames contribute 0 rather than a wrong number: a lag the
      // correlation could not find is not evidence of a lag of zero.
      feat[n * dims + d++] = (p.w[f] > 0 ? p.tau[f] : 0) * o.clusterTauScaleDb;
    }
  }

  // Deterministic farthest-point seeding. k-means++ would need randomness, and
  // a run whose answer moves between invocations is not something anyone can
  // reason about.
  const centroids = new Float64Array(K * dims);
  for (let d = 0; d < dims; d++) centroids[d] = feat[d];
  const dist2 = (a, ao, b, bo) => {
    let sum = 0;
    for (let d = 0; d < dims; d++) {
      const v = a[ao + d] - b[bo + d];
      sum += v * v;
    }
    return sum;
  };
  for (let c = 1; c < K; c++) {
    let bestN = 0;
    let bestD = -1;
    for (let n = 0; n < idx.length; n++) {
      let nearest = Infinity;
      for (let k = 0; k < c; k++) {
        const dd = dist2(feat, n * dims, centroids, k * dims);
        if (dd < nearest) nearest = dd;
      }
      if (nearest > bestD) { bestD = nearest; bestN = n; }
    }
    for (let d = 0; d < dims; d++) centroids[c * dims + d] = feat[bestN * dims + d];
  }

  const owner = new Int32Array(idx.length);
  const counts = new Int32Array(K);
  for (let iter = 0; iter < o.clusterIters; iter++) {
    let moved = 0;
    for (let n = 0; n < idx.length; n++) {
      let bestK = 0;
      let bestD = Infinity;
      for (let k = 0; k < K; k++) {
        const dd = dist2(feat, n * dims, centroids, k * dims);
        if (dd < bestD) { bestD = dd; bestK = k; }
      }
      if (owner[n] !== bestK) { owner[n] = bestK; moved++; }
    }
    centroids.fill(0);
    counts.fill(0);
    for (let n = 0; n < idx.length; n++) {
      const k = owner[n];
      counts[k]++;
      for (let d = 0; d < dims; d++) centroids[k * dims + d] += feat[n * dims + d];
    }
    for (let k = 0; k < K; k++) {
      if (!counts[k]) continue;
      for (let d = 0; d < dims; d++) centroids[k * dims + d] /= counts[k];
    }
    if (!moved) break;
  }

  // Which mic owns each group.
  //
  // Read from ALL the cues averaged over every frame in the group, not from the
  // centroid's timing dims alone. Timing was the obvious choice — it is the one
  // half of the fingerprint that ignores trims — but with mics nearly
  // equidistant those dims are a fraction of a millisecond and mostly noise, and
  // the groups then separate correctly while getting labelled wrongly. Averaging
  // the cues over hundreds of frames is what makes this robust; doing it per
  // frame is what the whole approach exists to avoid.
  const clusterWinner = new Int32Array(K).fill(-1);
  const affinity = [];
  for (let k = 0; k < K; k++) {
    const row = new Float64Array(K).fill(-Infinity);
    if (counts[k]) {
      for (let m = 0; m < K; m++) {
        let sum = 0;
        let n2 = 0;
        for (let n = 0; n < idx.length; n++) {
          if (owner[n] !== k) continue;
          const f = idx[n];
          sum += attribution.nLevelDb[m][f]
            + o.leadGainDb * attribution.lead[m][f]
            + (attribution.nTiltDb ? o.tiltWeight * attribution.nTiltDb[m][f] : 0);
          n2++;
        }
        row[m] = n2 ? sum / n2 : -Infinity;
      }
    }
    affinity.push(row);
  }

  // ONE MIC PER GROUP. Taking each group's best mic independently let two
  // groups pick the same one, which left a third mic that could never win a
  // frame — and that mic is somebody, ducked through their own dialogue. There
  // are K groups and K mics, so the assignment is a matching, not K separate
  // votes. Greedy on the strongest pair each time: with K this small it is the
  // optimal assignment in practice, and it is obvious to read.
  const takenK = new Uint8Array(K);
  const takenM = new Uint8Array(K);
  for (let step = 0; step < K; step++) {
    let bK = -1;
    let bM = -1;
    let best = -Infinity;
    for (let k = 0; k < K; k++) {
      if (takenK[k] || !counts[k]) continue;
      for (let m = 0; m < K; m++) {
        if (takenM[m]) continue;
        if (affinity[k][m] > best) { best = affinity[k][m]; bK = k; bM = m; }
      }
    }
    if (bK < 0 || bM < 0) break;
    clusterWinner[bK] = bM;
    takenK[bK] = 1;
    takenM[bM] = 1;
  }

  const assign = new Int32Array(nFrames).fill(-1);
  const confidence = new Float64Array(nFrames);
  for (let n = 0; n < idx.length; n++) {
    const f = idx[n];
    assign[f] = owner[n];
    let d1 = Infinity;
    let d2 = Infinity;
    for (let k = 0; k < K; k++) {
      const dd = dist2(feat, n * dims, centroids, k * dims);
      if (dd < d1) { d2 = d1; d1 = dd; } else if (dd < d2) { d2 = dd; }
    }
    // How much more this frame belongs to its own group than to the next one.
    confidence[f] = d2 > 0 && Number.isFinite(d2) ? clamp((d2 - d1) / (d2 + 1e-12), 0, 1) : 0;
  }

  let used = 0;
  for (let k = 0; k < K; k++) if (counts[k]) used++;

  // How cleanly the groups separated, as the mean margin between a frame's own
  // group and the next nearest. Reported either way so a caller can see WHY
  // clustering was or was not used.
  let qSum = 0;
  for (let n = 0; n < idx.length; n++) qSum += confidence[idx[n]];
  const quality = idx.length ? qSum / idx.length : 0;
  // Agreement with the plain per-frame argmax, over the frames both have an
  // opinion on.
  let agree = 0;
  let judged = 0;
  for (let n = 0; n < idx.length; n++) {
    const f = idx[n];
    const cw = clusterWinner[owner[n]];
    if (cw < 0) continue;
    let bestM = 0;
    let best = -Infinity;
    for (let m = 0; m < K; m++) {
      const e = attribution.nLevelDb[m][f]
        + o.leadGainDb * attribution.lead[m][f]
        + (attribution.nTiltDb ? o.tiltWeight * attribution.nTiltDb[m][f] : 0);
      if (e > best) { best = e; bestM = m; }
    }
    judged++;
    if (bestM === cw) agree++;
  }
  const agreement = judged ? agree / judged : 0;
  const usable = used >= 2 && quality >= o.clusterMinQuality && agreement >= o.clusterMinAgreement;
  return {
    assign, clusterWinner, confidence, dims, quality, agreement, usable,
    clusters: used, frames: idx.length,
  };
}

function autoMixGains(attribution, opts) {
  const o = { ...AUTOMIX_DEFAULTS, ...opts };
  const K = attribution.micCount;
  const nFrames = attribution.nFrames;
  const fa = attribution.sampleRate;
  const hopSec = attribution.hop / fa;

  const cluster = (o.attribution === 'cluster' && attribution.cluster && attribution.cluster.usable)
    ? attribution.cluster
    : null;

  const evidence = [];
  for (let m = 0; m < K; m++) {
    const e = new Float64Array(nFrames);
    const lvl = attribution.nLevelDb[m];
    const ld = attribution.lead[m];
    const tilt = attribution.nTiltDb ? attribution.nTiltDb[m] : null;
    for (let f = 0; f < nFrames; f++) {
      e[f] = lvl[f] + o.leadGainDb * ld[f] + (tilt ? o.tiltWeight * tilt[f] : 0);
    }
    evidence.push(e);
  }

  const winner = new Int32Array(nFrames);
  const activity = new Float64Array(nFrames);
  const target = [];
  for (let m = 0; m < K; m++) target.push(new Float64Array(nFrames));

  // The target HOLDS its last confident decision through gaps rather than
  // relaxing to 0.
  //
  // Speech is mostly gaps. In each one there is no localisable source, so
  // coherence falls, activity falls, and a target computed as `activity * raw`
  // collapses to "open everything" several times a second. Combined with a
  // fast-opening envelope that is fatal: the gain rides the top and no duck
  // ever survives, no matter how cleanly the attribution separated the mics.
  // So a gap is treated as "no new information" — keep the last decision — and
  // only a gap long enough to be a real pause (holdFrames) decays it away.
  const idleRelease = Math.exp(-hopSec / Math.max(1e-6, o.releaseMs / 1000));
  const holdFramesTarget = Math.max(0, Math.round((o.holdMs / 1000) / hopSec));
  const lastRaw = new Float64Array(K);
  const smoothConf = new Float64Array(K);
  const gapCoefDeepen = Math.exp(-hopSec / Math.max(1e-6, o.gapSmoothMs / 1000));
  const gapCoefRelease = Math.exp(-hopSec / Math.max(1e-6, o.gapReleaseMs / 1000));
  let idle = 0;
  // Who currently holds the floor; -1 until someone does.
  let held = -1;
  let challenger = -1;
  let challengerFrames = 0;
  const yieldFrames = Math.max(1, Math.round((o.winnerYieldMs / 1000) / hopSec));

  for (let f = 0; f < nFrames; f++) {
    let best = -Infinity;
    let bestM = 0;
    for (let m = 0; m < K; m++) {
      if (evidence[m][f] > best) { best = evidence[m][f]; bestM = m; }
    }
    // The group's verdict outranks the per-frame scores: it was decided from
    // every frame that shares this frame's acoustic signature, not from this
    // one frame's cues.
    if (cluster && cluster.assign[f] >= 0) {
      const cw = cluster.clusterWinner[cluster.assign[f]];
      if (cw >= 0) { bestM = cw; best = evidence[cw][f]; }
    }

    // The sitting winner keeps the floor unless someone clearly beats it, OR
    // has been quietly ahead long enough that the margin stops being evidence
    // of anything.
    if (held >= 0 && bestM !== held) {
      if (bestM === challenger) challengerFrames++;
      else { challenger = bestM; challengerFrames = 1; }
      const persistent = challengerFrames >= yieldFrames;
      if (!persistent && best - evidence[held][f] < o.winnerHysteresisDb) {
        bestM = held;
        best = evidence[held][f];
      }
    } else if (bestM === held) {
      challenger = -1;
      challengerFrames = 0;
    }
    const act = attribution.levelActivity[f] * attribution.coherence[f];
    activity[f] = act;
    const active = act >= o.inactiveThreshold;
    winner[f] = active ? bestM : -1;

    if (active) {
      idle = 0;
      held = bestM;
      for (let m = 0; m < K; m++) {
        // maxDuckDb is a TARGET, not a ceiling on the evidence.
        //
        // This used to be `max(-maxDuckDb, e - best)`, i.e. duck by however
        // much the evidence happened to separate. That reads fine until you
        // ask for a deep duck: real material separates by 5-15 dB, so the cap
        // was never reached and raising it from 12 to 33 changed nothing at
        // all. The two questions — "how sure are we this mic is not the
        // speaker" and "how far down should it go when we are sure" — are
        // separate, and only the second one is the user's to set.
        // Depth from whichever is more certain: how far ahead the winner's
        // evidence is, or how firmly this frame belongs to its group.
        const gapConf = clamp((best - evidence[m][f]) / o.gapFullDb, 0, 1);
        const groupConf = (cluster && cluster.assign[f] >= 0 && m !== bestM)
          ? clamp(cluster.confidence[f] / o.clusterFullConfidence, 0, 1)
          : 0;
        const conf = Math.max(gapConf, groupConf);
        // Asymmetric: see gapSmoothMs and gapReleaseMs.
        const c = conf > smoothConf[m] ? gapCoefDeepen : gapCoefRelease;
        smoothConf[m] += (conf - smoothConf[m]) * (1 - c);
        lastRaw[m] = -o.maxDuckDb * smoothConf[m];
      }
    } else {
      idle++;
      // Past a real pause, let everything return to unity so room tone is not
      // left permanently attenuated.
      if (idle > holdFramesTarget) {
        for (let m = 0; m < K; m++) lastRaw[m] += (0 - lastRaw[m]) * (1 - idleRelease);
      }
    }
    for (let m = 0; m < K; m++) target[m][f] = lastRaw[m];
  }

  // Ballistics, per mic, at frame rate. Linear interpolation between frame
  // centres 16 ms apart is already a 16 ms slew limiter, so nothing further is
  // smoothed here — and an unconditional smoother would undo the asymmetry
  // between attack and release that this whole step exists to create.
  const attackCoef = Math.exp(-hopSec / Math.max(1e-6, o.attackMs / 1000));
  const releaseCoef = Math.exp(-hopSec / Math.max(1e-6, o.releaseMs / 1000));
  const lookCoef = Math.exp(-hopSec / Math.max(1e-6, o.lookaheadMs / 1000));
  const holdFrames = Math.max(0, Math.round((o.holdMs / 1000) / hopSec));

  const gainDb = [];
  for (let m = 0; m < K; m++) {
    const t = target[m];
    const held = new Float64Array(nFrames);
    let cur = nFrames ? t[0] : 0; // start settled, so there is no fade-in at the head
    let hold = 0;
    for (let f = 0; f < nFrames; f++) {
      // Fast to open, slow to close — a mic must never miss the start of its
      // own talker's word. This is the right polarity for an auto-mixer, and
      // it is only safe because the TARGET now holds its decision through
      // inter-syllable gaps (see the hold in the scoring loop above). While the
      // target dipped to 0 in every gap, this polarity snapped the gain wide
      // open ~10 times a second and no duck ever survived: real material gave
      // a 13.5 dB evidence separation and a 0.1 dB delivered duck.
      if (t[f] >= cur) {
        cur += (t[f] - cur) * (1 - attackCoef);
        hold = holdFrames;
      } else if (hold > 0) {
        hold--;
      } else {
        cur += (t[f] - cur) * (1 - releaseCoef);
      }
      held[f] = cur;
    }

    // Look-ahead: a reverse one-pole, combined with max. Because it is a max it
    // can only ever open the gain EARLIER — it is structurally incapable of
    // introducing ducking that the causal pass did not already have, which is
    // both the safety property and the thing the test asserts.
    const out = new Float64Array(nFrames);
    if (nFrames) {
      let rev = held[nFrames - 1];
      out[nFrames - 1] = held[nFrames - 1];
      for (let f = nFrames - 2; f >= 0; f--) {
        rev = held[f] + (rev - held[f]) * lookCoef;
        out[f] = rev > held[f] ? rev : held[f];
      }
    }
    gainDb.push(out);
  }

  // Per-mic speech level. Ducking decides WHO; this decides HOW LOUD, and
  // without it a mic set 16 dB hot is still 16 dB hot in the output whenever
  // its owner talks.
  //
  // Both modes work off a measurement of one person's own dialogue, which is
  // what attribution bought: refDb (p95 frame RMS) for 'match', speechLufs
  // (BS.1770, gated to the same frames) for 'target'. The difference is only
  // what they aim at — the median of the others, or a fixed number.
  //
  // WHY BOTH EXIST. 'match' cannot be expressed as 'target' with a computed
  // value: its aim point moves with the material, so it stays correct on a take
  // whose absolute level nobody has an opinion about. 'target' cannot be
  // expressed as 'match': no relative rule lands a delivery at -16 LUFS.
  const matchGainDb = new Float64Array(K);
  // Why a correction was not the one asked for: 'headroom' (up-gain would have
  // pushed the track towards clipping), 'range' (further than maxMatchDb), or
  // 'unmeasured' (nothing on this mic was identified as its own wearer — see
  // `measured` below). Reported rather than silently absorbed: a target that
  // cannot be reached on this material is something the operator has to be
  // told, not something to quietly miss by 6 dB.
  const matchClamp = new Array(K).fill(null);
  const matchWantedDb = new Float64Array(K);
  // If attribution never found a localisable source, refDb fell back to a plain
  // p95 that nothing corroborated — and a confident 14 dB level correction on
  // the strength of an estimate we already know failed is worse than doing
  // nothing. Real material hit exactly this: 0% active, and every track still
  // got moved.
  let activeCount = 0;
  for (let f = 0; f < nFrames; f++) if (winner[f] >= 0) activeCount++;
  const attributionWorked = nFrames > 0 && activeCount / nFrames > 0.05;
  // A mic attribution never caught leading has no measurement of its OWN
  // speech, only of whatever cleared its gate — which on a lav track is mostly
  // other people. Both refDb and speechLufs fall back to that, and moving a
  // track on it means amplifying bleed: real material hit exactly this, a
  // participant who never took the floor measured at -42 LUFS and asked for
  // +25 dB. The right answer for a mic we cannot identify is to leave it alone.
  //
  // The bar is low on purpose — leadRefMinFrames is well under a second of
  // clear leading — so this excludes only mics attribution genuinely failed on,
  // not quiet participants.
  const measured = attribution.ownFromLead
    || new Uint8Array(K).fill(1); // pre-dates the flag: assume measured
  const lufs = attribution.speechLufs;
  // 'target' needs a loudness measurement to aim with. Where there is none —
  // an analysis rate too low to K-weight, or no identified speech on any mic —
  // it degrades to 'match' rather than to nothing: making the tracks agree with
  // each other is most of the value, and it needs only refDb.
  const canTarget = o.levelMatch === 'target' && !!lufs
    && Array.prototype.some.call(lufs, (v, m) => measured[m] && Number.isFinite(v));
  let mode = o.levelMatch === 'off' ? 'off' : (canTarget ? 'target' : 'match');
  if (!attributionWorked) mode = 'off';

  if (mode !== 'off') {
    // How far each mic wants to move, before any of it is bounded.
    const wanted = new Float64Array(K).fill(NaN);
    if (mode === 'target') {
      for (let m = 0; m < K; m++) {
        if (measured[m] && Number.isFinite(lufs[m])) wanted[m] = o.targetLufs - lufs[m];
      }
    } else {
      // Aim at the MEDIAN speaking level, not the loudest or the quietest.
      // Matching everyone up to the loudest pushes quiet mics into clipping;
      // matching down to the quietest throws away 20 dB on your best track. The
      // median moves each mic the least distance to a common level.
      const refs = [];
      for (let m = 0; m < K; m++) {
        if (measured[m] && attribution.refDb[m] !== 0) refs.push(attribution.refDb[m]);
      }
      if (refs.length) {
        refs.sort((a, b) => a - b);
        const median = refs[Math.floor((refs.length - 1) / 2)];
        for (let m = 0; m < K; m++) {
          // No usable reference; leave it alone — and keep it out of the median
          // it would otherwise drag toward a level that is not anybody's voice.
          if (measured[m] && attribution.refDb[m] !== 0) wanted[m] = median - attribution.refDb[m];
        }
      }
    }

    for (let m = 0; m < K; m++) {
      if (!Number.isFinite(wanted[m])) {
        if (!measured[m]) matchClamp[m] = 'unmeasured';
        continue;
      }
      matchWantedDb[m] = wanted[m];
      // Upward gain is bounded by the mic's own headroom. levelDb is frame RMS,
      // so a crest-factor allowance stands in for a true peak we never measured
      // — deliberately generous, because clipping a track is a far worse
      // outcome than leaving it a few dB quiet.
      let loudestFrame = -Infinity;
      for (let f = 0; f < nFrames; f++) {
        if (attribution.levelDb[m][f] > loudestFrame) loudestFrame = attribution.levelDb[m][f];
      }
      const headroomDb = Math.max(0, -1 - (loudestFrame + o.crestAllowanceDb));
      const ceiling = Math.min(o.maxMatchDb, headroomDb);
      const g = clamp(wanted[m], -o.maxMatchDb, ceiling);
      matchGainDb[m] = g;
      if (g < wanted[m] - 0.05) matchClamp[m] = headroomDb < o.maxMatchDb ? 'headroom' : 'range';
      else if (g > wanted[m] + 0.05) matchClamp[m] = 'range';
    }
  }
  // NOT folded into gainDb. The duck is time-varying and the match is a
  // constant, and mixing them makes the curve impossible to reason about — a
  // "duck depth" measured off the combined curve would include a level
  // correction that is not a duck at all. Consumers add it when they write
  // keyframes or render, where a constant offset is exactly what it is.

  const micStats = [];
  for (let m = 0; m < K; m++) {
    let wins = 0;
    let open = 0;
    let sum = 0;
    for (let f = 0; f < nFrames; f++) {
      if (winner[f] === m) wins++;
      if (gainDb[m][f] > -1) open++;
      sum += gainDb[m][f];
    }
    // Reported as null rather than as the fallback number when attribution
    // never identified this mic's wearer: that number is not their speech, and
    // printing it next to a target invites reading it as one.
    const inLufs = (lufs && measured[m]) ? lufs[m] : -Infinity;
    micStats.push({
      matchGainDb: matchGainDb[m],
      matchWantedDb: matchWantedDb[m],
      matchClamp: matchClamp[m],
      // What this mic's own dialogue measured, and where the correction leaves
      // it. outLufs is what the operator asked for whenever matchClamp is null.
      speechLufs: Number.isFinite(inLufs) ? inLufs : null,
      outLufs: Number.isFinite(inLufs) ? inLufs + matchGainDb[m] : null,
      winnerFraction: nFrames ? wins / nFrames : 0,
      openFraction: nFrames ? open / nFrames : 0,
      meanDuckDb: nFrames ? sum / nFrames : 0,
    });
  }
  let active = 0;
  for (let f = 0; f < nFrames; f++) if (winner[f] >= 0) active++;

  return {
    gainDb,
    winner,
    evidence,
    activity,
    matchGainDb,
    report: {
      frames: nFrames,
      frameRateHz: fa / attribution.hop,
      activeFraction: nFrames ? active / nFrames : 0,
      // What levelMatch actually did, which is not always what was asked for —
      // see `canTarget` and `attributionWorked`.
      levelMatch: mode,
      targetLufs: mode === 'target' ? o.targetLufs : null,
      micStats,
    },
  };
}

/**
 * Reduce a per-frame gain curve to a sparse keyframe list.
 *
 * Curve mode's whole payload. At 62.5 fps a five-minute take is 18 750 points
 * per mic, which is not something anyone wants on a timeline — Douglas-Peucker
 * with a vertical tolerance in dB brings that to the low hundreds while
 * bounding the error explicitly.
 *
 * Deviation is measured VERTICALLY, not perpendicular to the chord: the axes
 * are seconds and decibels, and a perpendicular distance between them would be
 * a number with no meaning.
 *
 * The host is assumed to interpolate between keyframes LINEARLY. If it is ever
 * pointed at a bezier or hold interpolation instead, maxErrorDb stops being a
 * bound and this needs revisiting.
 *
 * @param {Float64Array} gainDb per frame
 * @param {Float64Array} frameCenters per frame, in analysis-rate samples
 * @returns {{ keys: Array<{timeSec, gainDb}>, maxErrorDb, kept, dropped }}
 */
function simplifyGainCurve(gainDb, frameCenters, opts) {
  const o = { ...AUTOMIX_DEFAULTS, ...opts };
  const fa = o.sampleRate;
  if (!fa) throw new Error('simplifyGainCurve: sampleRate required');
  const tol = Math.max(1e-9, o.keyframeToleranceDb);
  const n = gainDb.length;
  if (!n) return { keys: [], maxErrorDb: 0, kept: 0, dropped: 0 };

  const keep = new Uint8Array(n);
  keep[0] = 1;
  keep[n - 1] = 1;
  // Iterative, not recursive: 18 750 points would put a naive recursion far
  // past any sane stack depth on a pathological curve.
  const stack = [[0, n - 1]];
  while (stack.length) {
    const seg = stack.pop();
    const lo = seg[0];
    const hi = seg[1];
    if (hi - lo < 2) continue;
    const x0 = frameCenters[lo];
    const y0 = gainDb[lo];
    const dx = frameCenters[hi] - x0;
    const dy = gainDb[hi] - y0;
    let bestI = -1;
    let bestD = tol;
    for (let i = lo + 1; i < hi; i++) {
      const t = dx !== 0 ? (frameCenters[i] - x0) / dx : 0;
      const d = Math.abs(gainDb[i] - (y0 + dy * t));
      if (d > bestD) { bestD = d; bestI = i; }
    }
    if (bestI >= 0) {
      keep[bestI] = 1;
      stack.push([lo, bestI]);
      stack.push([bestI, hi]);
    }
  }

  const keys = [];
  const idx = [];
  for (let i = 0; i < n; i++) {
    if (!keep[i]) continue;
    idx.push(i);
    keys.push({ timeSec: frameCenters[i] / fa, gainDb: gainDb[i] });
  }

  // Report the error actually achieved rather than the tolerance asked for —
  // the caller should be able to log what it got, not what it hoped for.
  let maxErrorDb = 0;
  for (let k = 0; k + 1 < idx.length; k++) {
    const lo = idx[k];
    const hi = idx[k + 1];
    const x0 = frameCenters[lo];
    const y0 = gainDb[lo];
    const dx = frameCenters[hi] - x0;
    const dy = gainDb[hi] - y0;
    for (let i = lo + 1; i < hi; i++) {
      const t = dx !== 0 ? (frameCenters[i] - x0) / dx : 0;
      const d = Math.abs(gainDb[i] - (y0 + dy * t));
      if (d > maxErrorDb) maxErrorDb = d;
    }
  }

  return { keys, maxErrorDb, kept: keys.length, dropped: n - keys.length };
}

/**
 * Apply a frame-rate gain curve to one channel at the render rate.
 *
 * Mirrors the time-axis resample in align.js's renderChannel — walk the output
 * in render samples, map back to the analysis timebase, lerp, clamp at the ends
 * — and deliberately OMITS the value scaling that function applies. A delay is
 * in samples and has to be rescaled with the rate; a gain is dimensionless and
 * must not be.
 *
 * Auto-mix never resamples and never delays: with an all-zero curve the output
 * is bit-identical to the input. Interpolation is done on LINEAR gain, not dB —
 * across a 16 ms frame step of at most a decibel the difference is under
 * 0.03 dB, and it saves a pow per sample.
 *
 * Safe in place (pass opts.out === channel): the gain at a sample depends on no
 * neighbouring sample, so unlike the delay applier this needs no second buffer.
 *
 * @param {Float64Array} channel full extracted channel at renderRate
 * @param {Float64Array} gainDb per analysis frame
 * @param {Float64Array} frameCenters per frame, analysis-rate samples, uniform
 * @param {number} outLen output length in render-rate samples
 * @param {object} opts { analysisRate, renderRate, inOffset = 0, out = null }
 */
function applyGainCurve(channel, gainDb, frameCenters, outLen, opts) {
  const { analysisRate, renderRate, inOffset = 0, out = null } = opts || {};
  if (!analysisRate || !renderRate) {
    throw new Error('applyGainCurve: analysisRate and renderRate required');
  }
  const dst = out || new Float64Array(outLen);
  if (dst.length < outLen) {
    throw new Error(`applyGainCurve: out length ${dst.length} < ${outLen}`);
  }
  const n = gainDb.length;
  if (!n) {
    for (let i = 0; i < outLen; i++) dst[i] = channel[inOffset + i] || 0;
    return dst.length === outLen ? dst : dst.subarray(0, outLen);
  }

  const lin = new Float64Array(n);
  for (let f = 0; f < n; f++) lin[f] = Math.pow(10, gainDb[f] / 20);

  const scale = renderRate / analysisRate;
  const c0 = frameCenters[0];
  const hop = n > 1 ? frameCenters[1] - frameCenters[0] : 1;

  for (let i = 0; i < outLen; i++) {
    // One offset, in render samples, with the curve position derived from it.
    // Two offsets that have to agree is a bug factory.
    const analysisPos = (inOffset + i) / scale;
    let p = (analysisPos - c0) / hop;
    if (p <= 0) {
      dst[i] = channel[inOffset + i] * lin[0];
      continue;
    }
    if (p >= n - 1) {
      dst[i] = channel[inOffset + i] * lin[n - 1];
      continue;
    }
    const j = p | 0;
    const t = p - j;
    const g = lin[j] + (lin[j + 1] - lin[j]) * t;
    dst[i] = channel[inOffset + i] * g;
  }
  return dst.length === outLen ? dst : dst.subarray(0, outLen);
}

module.exports = { ATTRIB_DECIMATION, SYNC_SEARCH_MAX_MS, AUTOMIX_DEFAULTS, pairSyncOffset, measurePairLags, fitPairBaseline, attributeSpeakers, clusterSpeakers, autoMixGains, simplifyGainCurve, applyGainCurve };
